int main(){int q=64,kv=128,vs=0,ss[2]={200,100},vc=1,sc=2;int cb=0,co[2]={0,0},cc=0,ci=0;reference(&q,&kv,&vs,ss,&vc,&sc,&cb,co,&cc,&ci,1,1,1,64,64,1,2,false);int *dq,*dk,*dv,*ds,*dvc,*dsc,*db,*dbo,*dc,*dci;cudaMalloc(&dq,4);cudaMalloc(&dk,4);cudaMalloc(&dv,4);cudaMalloc(&ds,8);cudaMalloc(&dvc,4);cudaMalloc(&dsc,4);cudaMalloc(&db,4);cudaMalloc(&dbo,8);cudaMalloc(&dc,4);cudaMalloc(&dci,4);cudaMemcpy(dq,&q,4,cudaMemcpyHostToDevice);cudaMemcpy(dk,&kv,4,cudaMemcpyHostToDevice);cudaMemcpy(dv,&vs,4,cudaMemcpyHostToDevice);cudaMemcpy(ds,ss,8,cudaMemcpyHostToDevice);cudaMemcpy(dvc,&vc,4,cudaMemcpyHostToDevice);cudaMemcpy(dsc,&sc,4,cudaMemcpyHostToDevice);cudaMemset(db,0,4);cudaMemset(dbo,0,8);cudaMemset(dc,0,4);cudaMemset(dci,0,4);convert_vertical_slash_indexes_64x64_mergehead(dq,dk,dv,ds,dvc,dsc,db,dbo,dc,dci,1,1,1,64,64,1,2,false);cudaDeviceSynchronize();int gb=0,go[2]={0,0},gc=0,gi=0;cudaMemcpy(&gb,db,4,cudaMemcpyDeviceToHost);cudaMemcpy(go,dbo,8,cudaMemcpyDeviceToHost);cudaMemcpy(&gc,dc,4,cudaMemcpyDeviceToHost);cudaMemcpy(&gi,dci,4,cudaMemcpyDeviceToHost);printf("WITNESS CPU blocks=%d offsets=%d,%d columns=%d index=%d GPU blocks=%d offsets=%d,%d columns=%d index=%d CUDAerror=%s\n",cb,co[0],co[1],cc,ci,gb,go[0],go[1],gc,gi,cudaGetErrorString(cudaGetLastError()));return !(cb==0&&gb==1&&go[0]==28&&cc==1&&gc==1&&ci==0&&gi==0);}
